def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # List to store the path
    path = []

    # Function to trace back the path from goal to start
    def trace_back(predecessors, start, goal):
        current = goal
        while current != start:
            path.append(current)
            current = predecessors[current]
        path.append(start)
        path.reverse()
        return path

    # Initialize the predecessor dictionary and set the start's predecessor to None
    predecessors = {node: None for node in graph}
    frontier = [start]
    reached = {start: None}

    while frontier:
        current = frontier.pop(0)
        if current == goal:
            return trace_back(predecessors, start, goal)
        for neighbor in graph[current]:
            if neighbor not in reached:
                reached[neighbor] = current
                frontier.append(neighbor)
                predecessors[neighbor] = current
    return None
