def find_path(graph, start, goal):
    # Dictionary to keep track of visited nodes and the path to them
    visited = {start: [start]}

    # Stack to implement depth-first search (DFS)
    stack = [(start, [start])]

    while stack:
        (vertex, path) = stack.pop()
        if vertex in visited:
            continue

        visited[vertex] = path

        # If we have reached the goal, return the path
        if vertex == goal:
            return path

        # Explore neighboring nodes
        for neighbor in graph.get(vertex, []):
            if neighbor not in visited:
                stack.append((neighbor, path + [neighbor]))

    # If the goal is not reachable, return None
    return None
