    def dfs(graph, current, path, visited):
        visited.add(current)
        path.append(current)
        if current == goal:
            return True
        if current in graph:
            for neighbor in graph[current]:
                if neighbor not in visited:
                    if dfs(graph, neighbor, path, visited):
                        return True
        path.pop()
        visited.remove(current)
        return False

    visited = set()
    path = []
    if start not in graph or goal not in graph:
        return None
    if dfs(graph, start, path, visited):
        return path
    return None
